<script id="braze-js-blocker-fix-setup">
  // For dashboard previews
  (function () {
    var isDashboard = (function () {
      try {
        void window.top.document;
        return false;
      } catch (e) {
        return true;
      }
    })();

    if (isDashboard) {
      window.ibmSetup = {
        isDashboard,
        root: document.documentElement,
        frame: document.documentElement,
        parentWindow: window
      };
    } else {
      window.ibmSetup = {
        isDashboard,
        root: window.top.document.querySelector('.ab-iam-root'),
        frame: window.top.document.querySelector('iframe.ab-in-app-message'),
        parentWindow: window.top
      };
    }

    // handles bfcache
    window.onpageshow = function (event) {
      if (event.persisted) {
        window.ibmSetup.frame.remove();
      }
    };

    const frame = window.ibmSetup.frame;

    if (frame) {
      frame.dataset.backdrop = 'true';
      frame.setAttribute('name', 'ibmOptinFrame');
    }

    const mutationCallback = (list, observer) => {
      const offerTab = document.getElementById('offerTab');
      const overlay = document.getElementById('braze-optin-overlay');
      const offerTabEnabled = document.body?.dataset?.offerTab === 'true';

      if (offerTabEnabled && offerTab && overlay) {
        observer.disconnect();

        offerTab.style.top = 'calc(var(--offer-top) + var(--offer-size) + 4px)';

        offerTab.addEventListener('pointerdown', (e) => {
          frame?.classList.remove('overlayHidden');
        });

        overlay.addEventListener('animationend', () => {
          frame?.classList.add('overlayHidden');
        });
      }
    };

    new MutationObserver(mutationCallback).observe(document, {
      attributes: true,
      childList: true,
      subtree: true
    });

    const parentDocument = ibmSetup.parentWindow.document;
    const searchOverlay = parentDocument.querySelector('.search-overlay-landing');

    if (searchOverlay) {
      new MutationObserver(() => {
        const isHidden = searchOverlay.classList.contains('hidden');
        parentDocument.body.classList.toggle('hide-ibm', !isHidden);
      }).observe(searchOverlay, { attributes: true, attributeFilter: ['class'] });
    }
  })();
</script>

<script id="braze-js-blocker-fix-resize">
  (function () {
    // adjust size of the parent iframe
    const fix = document.getElementById('braze-css-blocker-fix-setup');
    window.ibmSetup.root?.appendChild(fix);

    // allows analytics to be captured by web SDK
    if (window.ibmSetup.frame) {
      window.ibmSetup.frame?.setAttribute('class', 'ab-start-hidden');
    }

    if (!window.ibmSetup.isDashboard) {
      setTimeout(function () {
        // allows scrolling while message is displayed
        window.top.document.body?.classList.remove('ab-pause-scrolling');
        // window.ibmSetup.root.setAttribute('class', '');
      }, 0);
    }
  })();
</script>





