<script id="js-offer-tab">
  const stickyClose = document.getElementById("closeOfferTabBtn");
  const stickyOpen = document.getElementById("offerBtn");
  const sticky = document.getElementById("offerTab");
  const abortSticky = new AbortController();
  const abortStickyOpts = { signal: abortSticky.signal };
  function handleBrazeEvents(overlayMinimized = false) {
    const customEvent = overlayMinimized ? "iam_optin_maximized" : "iam_optin_minimized";
    const customClick = overlayMinimized ? "offer_tab_closed" : "offer_tab_opened";
    window.appboyBridge.logCustomEvent(customEvent);
    window.appboyBridge.logClick(customClick);
  }
  function handleFocus(overlayMinimized = false) {
    if (overlayMinimized) sticky && stickyOpen.focus();
    else document.dispatchEvent(new Event("focusOnDismiss"));
  }
  function handleStickyState(overlayMinimized = false) {
    sticky && (sticky.dataset.overlayMinimized = overlayMinimized.toString());
    handleFocus(overlayMinimized);
    handleBrazeEvents(overlayMinimized);
  }
  function handleClose(forceUnmount = false) {
    const popup = document.getElementById("braze-optin-overlay");
    (forceUnmount || popup && popup.dataset.mode === "confirmed") && sendUnmountOptin();
    handleStickyState(true);
  }
  function handleOpen() {
    handleStickyState(false);
  }
  const handleStickyAnimation = (e) => {
    e.animationName === "fadeOut" && handleStickyState(true);
  };
  function handleOutsideClick(e) {
    if (e.target.closest("#closeOfferTabBtn")) return;
    const popup = document.getElementById("braze-optin-overlay");
    const target = e.target;
    const outsideOffertab = sticky && !sticky.contains(target);
    if (popup && !popup.contains(target) && outsideOffertab) handleClose();
  }
  function sendUnmountOptin() {
    document.dispatchEvent(new Event("unmountOptin"));
  }
  function unmountSticky() {
    abortSticky.abort();
    sticky && sticky.remove();
  }
  function addStickyEvent(element, event, handler, options = {}) {
    if (element) return element.addEventListener(event, handler, { ...options });
  }
  addStickyEvent(stickyClose, "click", () => handleClose(true), abortStickyOpts);
  addStickyEvent(stickyOpen, "click", handleOpen, abortStickyOpts);
  addStickyEvent(window.document, "unmountSticky", unmountSticky, { once: true });
  addStickyEvent(window.document, "click", handleOutsideClick, abortStickyOpts);
  let popupDismiss = document.getElementById("dismissBtn");
  addStickyEvent(popupDismiss, "click", () => handleClose(), abortStickyOpts);
  const stickySetup = (_list, observer) => {
    const popup = document.getElementById("braze-optin-overlay");
    if (popup) {
      observer.disconnect();
      if (!popupDismiss) {
        popupDismiss = document.getElementById("dismissBtn");
        addStickyEvent(popupDismiss, "click", () => handleClose(), abortStickyOpts);
      }
      addStickyEvent(popup, "animationend", handleStickyAnimation, abortStickyOpts);
    }
  };
  new MutationObserver(stickySetup).observe(window.document.body, {
    childList: true,
    subtree: true
  });
</script>
