  }

  function getSubGroupAttr(data) {
    const { number = null, email = null, emailOptins: { loyalty = false, promo = false } = {} } = data;

    let subGroupAttr;

    !!number && !!!email && (subGroupAttr = 'SMS_entered_sub_group');
