    !!email && !!number && (subGroupAttr = 'Email_SMS_entered_sub_group');
    loyalty && !promo && (subGroupAttr = 'Loyalty_entered_only');

    console.info(`Used "${subGroupAttr}" group attribute.`);

    return subGroupAttr;
  }

  async function sendToBraze(data) {
    const {
      number = null,
      email = null,
      lastSource = '',
      userId = '',
      emailOptins = {}
    } = data;

    const enteredBoth = !!number && !!email;
    const generalEmailMarketing = 'true' === 'false';
    const subGroupAttr = getSubGroupAttr(data);

    console.group('BRAZE JS');
    generalEmailMarketing && console.info('General marketing (non-loyalty)');
    enteredBoth && bridge().logClick('shp: added both email address and phone number');
