    !!number && console.info(`Phone entered ${number?.replace(/\d?/g, '*')}`);
    !enteredBoth && !!number && bridge().logClick('shp: added phone number');
    !generalEmailMarketing && !!emailOptins?.loyalty && console.info(`Opted into email loyalty.`);
    !!emailOptins?.promo && console.info(`Opted into email promo.`);

    console.group('FINAL');
    console.info(`Used "${lastSource}" for popup before sending.`);
    bridge().logCustomEvent('IBM_To_Shopify', {
      opted_into: subGroupAttr,
      opted_group_ts: `2026-11-09 19:04:04`,
      opted_source: lastSource,
      opted_email: !!email ? email : "",
