      opted_email_promo: !!emailOptins?.promo,
      opted_is_non_loyalty_ibm: generalEmailMarketing,
      opted_phone: !!number ? number : ""
    });
    bridge().requestImmediateDataFlush();
    console.groupEnd();
  }
